def gen(rng):
    import string
    def fmt(ws):
        return str(len(ws)) + '\n' + ' '.join(ws)
    def rw(k):
        return ''.join(rng.choice('abc') for _ in range(rng.randint(1, k)))
    tests = [fmt(['a']), fmt(['a', 'a']), fmt(['a', 'b']), fmt(['x'] * 10), fmt(['the', 'cat', 'and', 'the', 'dog', 'and', 'the', 'bird', 'fly']),
             fmt(['red', 'green', 'blue', 'yellow']), fmt(['na', 'na', 'na', 'na', 'batman'])]
    for n in (3, 5, 8, 12, 20, 30):
        for _ in range(2):
            tests.append(fmt([rw(2) for _ in range(n)]))
    for n in (10, 25):
        pool = [rw(4) for _ in range(8)]
        tests.append(fmt([rng.choice(pool) for _ in range(n)]))
    n = 100000
    letters = string.ascii_lowercase
    def big(k):
        return ''.join(rng.choice(letters) for _ in range(rng.randint(1, k)))
    tests.append(fmt([big(10) for _ in range(n)]))
    pool = [big(10) for _ in range(500)]
    tests.append(fmt([rng.choice(pool) for _ in range(n)]))
    tests.append(fmt(['abcdefghij'] * n))
    pool2 = [big(4) for _ in range(40000)]
    tests.append(fmt([rng.choice(pool2) for _ in range(n)]))
    return tests
